#toc {
  position: fixed !important;
  top: 130px;
  right: 1rem;
  width: 240px;
  max-height: calc(100vh - 150px);
  overflow-y: auto;
  z-index: 5;
  margin: 0 !important;
  box-sizing: border-box;
  padding: 0.5rem 0.75rem;
  background: Canvas;
  color: CanvasText;
  border: 1px solid rgba(128, 128, 128, 0.25);
  border-radius: 6px;
}
#apicontent {
  margin-right: 260px;
}
